use std::env;
use std::fs;
use std::path::Path;
use std::process::ExitCode;

mod elf;
mod report;

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: elfcat <filename>");
        eprintln!("Writes <filename>.html to CWD.");
        return ExitCode::from(0);
    }
    let filename = &args[1];
    let data = match fs::read(filename) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("Failed to read file {:?}: {}", filename, e);
            return ExitCode::from(1);
        }
    };

    let parsed = match elf::parser::parse(&data) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("Failed to parse ELF: {}", e);
            return ExitCode::from(1);
        }
    };

    let basename = Path::new(filename)
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| filename.clone());
    let out_path = format!("{}.html", basename);

    let html = report::generate(filename, &parsed);
    if let Err(e) = fs::write(&out_path, html) {
        eprintln!("Failed to write {:?}: {}", out_path, e);
        return ExitCode::from(1);
    }
    ExitCode::from(0)
}
MAINRS
