// ELF constants and types

pub const EI_NIDENT: usize = 16;
pub const EI_CLASS: usize = 4;
pub const EI_DATA: usize = 5;
pub const EI_VERSION: usize = 6;
pub const EI_OSABI: usize = 7;
pub const EI_ABIVERSION: usize = 8;

pub const ELFMAG: [u8; 4] = [0x7f, b'E', b'L', b'F'];

pub const ELFCLASS32: u8 = 1;
pub const ELFCLASS64: u8 = 2;

pub const ELFDATA2LSB: u8 = 1;
pub const ELFDATA2MSB: u8 = 2;

pub const ET_NONE: u16 = 0;
pub const ET_REL: u16 = 1;
pub const ET_EXEC: u16 = 2;
pub const ET_DYN: u16 = 3;
pub const ET_CORE: u16 = 4;

#[derive(Debug, Clone, Copy)]
pub enum Bitness {
    B32,
    B64,
}

#[derive(Debug, Clone, Copy)]
pub enum Endianness {
    Little,
    Big,
}

#[derive(Debug, Clone)]
pub struct Phdr {
    pub p_type: u32,
    pub p_flags: u32,
    pub p_offset: u64,
    pub p_vaddr: u64,
    pub p_paddr: u64,
    pub p_filesz: u64,
    pub p_memsz: u64,
    pub p_align: u64,
}

#[derive(Debug, Clone)]
pub struct Shdr {
    pub sh_name: u32,
    pub sh_type: u32,
    pub sh_flags: u64,
    pub sh_addr: u64,
    pub sh_offset: u64,
    pub sh_size: u64,
    pub sh_link: u32,
    pub sh_info: u32,
    pub sh_addralign: u64,
    pub sh_entsize: u64,
    pub name: String,
}

#[derive(Debug)]
pub struct Ehdr {
    pub e_ident: [u8; EI_NIDENT],
    pub e_type: u16,
    pub e_machine: u16,
    pub e_version: u32,
    pub e_entry: u64,
    pub e_phoff: u64,
    pub e_shoff: u64,
    pub e_flags: u32,
    pub e_ehsize: u16,
    pub e_phentsize: u16,
    pub e_phnum: u16,
    pub e_shentsize: u16,
    pub e_shnum: u16,
    pub e_shstrndx: u16,
}

#[derive(Debug)]
pub struct ParsedElf<'a> {
    pub data: &'a [u8],
    pub bitness: Bitness,
    pub endianness: Endianness,
    pub ehdr: Ehdr,
    pub phdrs: Vec<Phdr>,
    pub shdrs: Vec<Shdr>,
}

pub fn bitness_name(b: Bitness) -> &'static str {
    match b {
        Bitness::B32 => "32-bit",
        Bitness::B64 => "64-bit",
    }
}

pub fn endianness_name(e: Endianness) -> &'static str {
    match e {
        Endianness::Little => "Little endian",
        Endianness::Big => "Big endian",
    }
}

// Get ABI name and whether it's "common" (SysV)
pub fn osabi_name(abi: u8) -> (&'static str, bool) {
    match abi {
        0 => ("SysV", true),
        1 => ("HP-UX", false),
        2 => ("NetBSD", false),
        3 => ("Linux", false),
        4 => ("GNU Hurd", false),
        6 => ("Solaris", false),
        7 => ("AIX", false),
        8 => ("IRIX", false),
        9 => ("FreeBSD", false),
        10 => ("Tru64", false),
        11 => ("Novell Modesto", false),
        12 => ("OpenBSD", false),
        13 => ("OpenVMS", false),
        14 => ("NonStop Kernel", false),
        15 => ("AROS", false),
        16 => ("FenixOS", false),
        17 => ("CloudABI", false),
        _ => ("Unknown", false),
    }
}

pub fn e_type_name(t: u16) -> String {
    match t {
        ET_NONE => "No file type (NONE)".to_string(),
        ET_REL => "Relocatable object file (REL)".to_string(),
        ET_EXEC => "Executable file (EXEC)".to_string(),
        ET_DYN => "Shared object file (DYN)".to_string(),
        ET_CORE => "Core file (CORE)".to_string(),
        v if (0xfe00..=0xfeff).contains(&v) => format!("OS-specific: {:#x}", v),
        v if (0xff00..=0xffff).contains(&v) => format!("Processor-specific: {:#x}", v),
        v => format!("Unknown: {:#x}", v),
    }
}

pub fn e_machine_name(m: u16) -> &'static str {
    match m {
        0 => "None",
        1 => "AT&T WE 32100",
        2 => "SPARC",
        3 => "Intel 80386",
