use super::types::*;

pub fn parse(data: &[u8]) -> Result<ParsedElf, String> {
    if data.len() < EI_NIDENT {
        return Err("file is smaller than ELF header's e_ident".into());
    }
    if data[0..4] != ELFMAG {
        return Err("mismatched magic: not an ELF file".into());
    }
    let bitness = match data[EI_CLASS] {
        ELFCLASS32 => Bitness::B32,
        ELFCLASS64 => Bitness::B64,
        v => return Err(format!("Unknown bitness: {}", v)),
    };
    let endianness = match data[EI_DATA] {
        ELFDATA2LSB => Endianness::Little,
        ELFDATA2MSB => Endianness::Big,
        v => return Err(format!("Unknown endianness: {}", v)),
    };

    let mut r = Reader { data, pos: 0, endianness };
    let mut e_ident = [0u8; EI_NIDENT];
    e_ident.copy_from_slice(&data[..EI_NIDENT]);
    r.pos = EI_NIDENT;

    let e_type = r.u16();
    let e_machine = r.u16();
    let e_version = r.u32();
    let (e_entry, e_phoff, e_shoff) = match bitness {
        Bitness::B32 => (r.u32() as u64, r.u32() as u64, r.u32() as u64),
        Bitness::B64 => (r.u64(), r.u64(), r.u64()),
    };
    let e_flags = r.u32();
    let e_ehsize = r.u16();
    let e_phentsize = r.u16();
    let e_phnum = r.u16();
    let e_shentsize = r.u16();
    let e_shnum = r.u16();
    let e_shstrndx = r.u16();

    let ehdr = Ehdr {
        e_ident,
        e_type,
        e_machine,
        e_version,
        e_entry,
        e_phoff,
        e_shoff,
        e_flags,
        e_ehsize,
        e_phentsize,
        e_phnum,
        e_shentsize,
        e_shnum,
        e_shstrndx,
    };

    // Parse phdrs
    let mut phdrs = Vec::with_capacity(e_phnum as usize);
    for i in 0..(e_phnum as usize) {
        let off = (e_phoff as usize) + i * (e_phentsize as usize);
        r.pos = off;
        let phdr = match bitness {
            Bitness::B32 => {
                let p_type = r.u32();
                let p_offset = r.u32() as u64;
                let p_vaddr = r.u32() as u64;
                let p_paddr = r.u32() as u64;
                let p_filesz = r.u32() as u64;
                let p_memsz = r.u32() as u64;
                let p_flags = r.u32();
                let p_align = r.u32() as u64;
                Phdr { p_type, p_flags, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align }
            }
            Bitness::B64 => {
                let p_type = r.u32();
                let p_flags = r.u32();
                let p_offset = r.u64();
                let p_vaddr = r.u64();
                let p_paddr = r.u64();
                let p_filesz = r.u64();
                let p_memsz = r.u64();
                let p_align = r.u64();
                Phdr { p_type, p_flags, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_align }
            }
        };
        phdrs.push(phdr);
    }

    // Parse shdrs
    let mut shdrs = Vec::with_capacity(e_shnum as usize);
    for i in 0..(e_shnum as usize) {
        let off = (e_shoff as usize) + i * (e_shentsize as usize);
        r.pos = off;
        let shdr = match bitness {
            Bitness::B32 => {
                let sh_name = r.u32();
                let sh_type = r.u32();
                let sh_flags = r.u32() as u64;
                let sh_addr = r.u32() as u64;
                let sh_offset = r.u32() as u64;
                let sh_size = r.u32() as u64;
                let sh_link = r.u32();
                let sh_info = r.u32();
                let sh_addralign = r.u32() as u64;
                let sh_entsize = r.u32() as u64;
                Shdr {
                    sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size,
                    sh_link, sh_info, sh_addralign, sh_entsize, name: String::new(),
                }
            }
            Bitness::B64 => {
                let sh_name = r.u32();
                let sh_type = r.u32();
                let sh_flags = r.u64();
                let sh_addr = r.u64();
                let sh_offset = r.u64();
                let sh_size = r.u64();
                let sh_link = r.u32();
                let sh_info = r.u32();
                let sh_addralign = r.u64();
                let sh_entsize = r.u64();
                Shdr {
                    sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size,
                    sh_link, sh_info, sh_addralign, sh_entsize, name: String::new(),
                }
            }
        };
        shdrs.push(shdr);
    }

    // Populate section names using shstrtab
    if (e_shstrndx as usize) < shdrs.len() {
        let strtab = &shdrs[e_shstrndx as usize];
        let start = strtab.sh_offset as usize;
        let end = start + strtab.sh_size as usize;
        let strtab_data: &[u8] = if end <= data.len() { &data[start..end] } else { &[] };
        for s in shdrs.iter_mut() {
            let nstart = s.sh_name as usize;
            if nstart < strtab_data.len() {
                let mut n = nstart;
                while n < strtab_data.len() && strtab_data[n] != 0 {
                    n += 1;
                }
                s.name = String::from_utf8_lossy(&strtab_data[nstart..n]).into_owned();
            }
        }
    }

    Ok(ParsedElf {
        data,
        bitness,
        endianness,
        ehdr,
        phdrs,
        shdrs,
    })
}

struct Reader<'a> {
    data: &'a [u8],
    pos: usize,
    endianness: Endianness,
}

impl<'a> Reader<'a> {
    fn u16(&mut self) -> u16 {
        let b = [self.data[self.pos], self.data[self.pos + 1]];
        self.pos += 2;
        match self.endianness {
            Endianness::Little => u16::from_le_bytes(b),
            Endianness::Big => u16::from_be_bytes(b),
        }
    }
    fn u32(&mut self) -> u32 {
        let mut b = [0u8; 4];
        b.copy_from_slice(&self.data[self.pos..self.pos + 4]);
        self.pos += 4;
        match self.endianness {
            Endianness::Little => u32::from_le_bytes(b),
            Endianness::Big => u32::from_be_bytes(b),
        }
    }
    fn u64(&mut self) -> u64 {
        let mut b = [0u8; 8];
        b.copy_from_slice(&self.data[self.pos..self.pos + 8]);
        self.pos += 8;
        match self.endianness {
            Endianness::Little => u64::from_le_bytes(b),
            Endianness::Big => u64::from_be_bytes(b),
        }
    }
}
