use super::types::*;

pub fn parse(data: &[u8]) -> Result<ParsedElf, String> {
    if data.len() < EI_NIDENT {
        return Err("file is smaller than ELF header's e_ident".into());
    }
    if data[0..4] != ELFMAG {
        return Err("mismatched magic: not an ELF file".into());
    }
    let bitness = match data[EI_CLASS] {
        ELFCLASS32 => Bitness::B32,
        ELFCLASS64 => Bitness::B64,
        v => return Err(format!("Unknown bitness: {}", v)),
    };
    let endianness = match data[EI_DATA] {
        ELFDATA2LSB => Endianness::Little,
        ELFDATA2MSB => Endianness::Big,
        v => return Err(format!("Unknown endianness: {}", v)),
    };

    let mut r = Reader { data, pos: 0, endianness };
    let mut e_ident = [0u8; EI_NIDENT];
    e_ident.copy_from_slice(&data[..EI_NIDENT]);
    r.pos = EI_NIDENT;

    let e_type = r.u16();
    let e_machine = r.u16();
    let e_version = r.u32();
    let (e_entry, e_phoff, e_shoff) = match bitness {
        Bitness::B32 => (r.u32() as u64, r.u32() as u64, r.u32() as u64),
        Bitness::B64 => (r.u64(), r.u64(), r.u64()),
    };
    let e_flags = r.u32();
    let e_ehsize = r.u16();
    let e_phentsize = r.u16();
    let e_phnum = r.u16();
    let e_shentsize = r.u16();
    let e_shnum = r.u16();
    let e_shstrndx = r.u16();

