// ---------- Range-based bytes rendering ----------

#[derive(Debug, Clone)]
struct Range {
    start: usize,
    end: usize,    // exclusive
    open: String,
    // sort key: smaller opens first
    // within same start/end, use priority (lower opens first)
    prio: u32,
    idx: u32,
}

fn write_bytes(out: &mut String, e: &ParsedElf) {
    let data = e.data;
    let ranges = collect_ranges(e);

    // Group ranges by start position
    let mut starts: std::collections::HashMap<usize, Vec<&Range>> = std::collections::HashMap::new();
    for r in &ranges {
        starts.entry(r.start).or_default().push(r);
    }
    for v in starts.values_mut() {
        v.sort_by_key(|r| (std::cmp::Reverse(r.end), r.prio, r.idx));
    }

    out.push_str("    <div id='bytes'>");

    let mut stack: Vec<(usize, &str)> = Vec::new(); // (end, close_str)

    let n = data.len();
    for b in 0..n {
        // Open new ranges starting at b
        if let Some(v) = starts.get(&b) {
            for r in v {
                out.push_str(&r.open);
                stack.push((r.end, "</span>"));
            }
        }

        // Emit byte
        emit_byte(out, data[b], b);

        // Close spans ending at b+1
        while let Some(&(end, _)) = stack.last() {
            if end == b + 1 {
                out.pop_or_push_str();
                let (_, cl) = stack.pop().unwrap();
                out.push_str(cl);
            } else {
                break;
            }
        }

        // Emit separator
        if b < n - 1 {
            if (b + 1) % 16 == 0 {
                out.push('\n');
            } else {
                out.push(' ');
            }
        }
    }

    // Close any remaining spans
    while let Some((_, cl)) = stack.pop() {
        out.push_str(cl);
    }

    out.push_str("</div>\n");
}

trait StrExt {
    fn pop_or_push_str(&mut self);
}
impl StrExt for String {
    fn pop_or_push_str(&mut self) {}
}

fn emit_byte(out: &mut String, b: u8, pos: usize) {
    // Magic bytes: bytes 0..=3, render printable as &nbsp;X
    if pos < 4 {
        if (0x20..=0x7e).contains(&b) {
            out.push_str("&nbsp;");
            out.push(b as char);
            return;
        }
    }
    out.push_str(&format!("{:02x}", b));
}

fn collect_ranges(e: &ParsedElf) -> Vec<Range> {
    let mut v: Vec<Range> = Vec::new();
    let bits = e.bitness;
    let ehdr_size: usize = match bits {
        Bitness::B32 => 52,
        Bitness::B64 => 64,
    };

    // ehdr
    v.push(Range {
        start: 0,
        end: ehdr_size,
        open: "<span class='ehdr'>".into(),
        prio: 10,
        idx: 0,
    });
    // ident
    v.push(Range {
        start: 0,
        end: EI_NIDENT,
        open: "<span class='ident'>".into(),
        prio: 15,
        idx: 0,
    });
    // ident fields
    v.push(Range { start: 0, end: 4, open: "<span class='magic'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: 4, end: 5, open: "<span class='class'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: 5, end: 6, open: "<span class='data'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: 6, end: 7, open: "<span class='ver'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: 7, end: 8, open: "<span class='abi'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: 8, end: 9, open: "<span class='abi_ver'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: 9, end: 16, open: "<span class='pad'>".into(), prio: 20, idx: 0 });

    // ehdr fields
    let (e_type_off, e_machine_off, e_version_off, e_entry_off, e_phoff_off, e_shoff_off,
         e_flags_off, e_ehsize_off, e_phentsize_off, e_phnum_off, e_shentsize_off,
         e_shnum_off, e_shstrndx_off);
    match bits {
        Bitness::B32 => {
            e_type_off = 16;
            e_machine_off = 18;
            e_version_off = 20;
            e_entry_off = 24;
            e_phoff_off = 28;
            e_shoff_off = 32;
            e_flags_off = 36;
            e_ehsize_off = 40;
            e_phentsize_off = 42;
            e_phnum_off = 44;
            e_shentsize_off = 46;
            e_shnum_off = 48;
            e_shstrndx_off = 50;
        }
        Bitness::B64 => {
            e_type_off = 16;
            e_machine_off = 18;
            e_version_off = 20;
            e_entry_off = 24;
            e_phoff_off = 32;
            e_shoff_off = 40;
            e_flags_off = 48;
            e_ehsize_off = 52;
            e_phentsize_off = 54;
            e_phnum_off = 56;
            e_shentsize_off = 58;
            e_shnum_off = 60;
            e_shstrndx_off = 62;
        }
    }
    let word = match bits { Bitness::B32 => 4, Bitness::B64 => 8 };
    v.push(Range { start: e_type_off, end: e_type_off+2, open: "<span class='e_type'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_machine_off, end: e_machine_off+2, open: "<span class='e_machine'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_version_off, end: e_version_off+4, open: "<span class='e_version'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_entry_off, end: e_entry_off+word, open: "<span class='e_entry'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_phoff_off, end: e_phoff_off+word, open: "<span class='e_phoff'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_shoff_off, end: e_shoff_off+word, open: "<span class='e_shoff'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_flags_off, end: e_flags_off+4, open: "<span class='e_flags'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_ehsize_off, end: e_ehsize_off+2, open: "<span class='e_ehsize'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_phentsize_off, end: e_phentsize_off+2, open: "<span class='e_phentsize'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_phnum_off, end: e_phnum_off+2, open: "<span class='e_phnum'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_shentsize_off, end: e_shentsize_off+2, open: "<span class='e_shentsize'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_shnum_off, end: e_shnum_off+2, open: "<span class='e_shnum'>".into(), prio: 20, idx: 0 });
    v.push(Range { start: e_shstrndx_off, end: e_shstrndx_off+2, open: "<span class='e_shstrndx'>".into(), prio: 20, idx: 0 });

    // Segments (those with p_offset != 0 and p_filesz > 0)
    for (i, p) in e.phdrs.iter().enumerate() {
        if p.p_offset == 0 || p.p_filesz == 0 { continue; }
        let start = p.p_offset as usize;
        let end = start + p.p_filesz as usize;
        if end > e.data.len() { continue; }
        v.push(Range {
            start,
            end,
            open: format!("<span class='bin_segment{} segment'>", i),
            prio: 40,
            idx: i as u32,
        });
    }

    // Phdr entries (each phdr at phoff + i*phentsize)
    let phentsize = e.ehdr.e_phentsize as usize;
    let phoff = e.ehdr.e_phoff as usize;
    for (i, p) in e.phdrs.iter().enumerate() {
        let start = phoff + i * phentsize;
        let end = start + phentsize;
        if end > e.data.len() { continue; }
        v.push(Range {
            start,
            end,
            open: format!("<span class='bin_phdr{} phdr'>", i),
            prio: 50,
            idx: i as u32,
        });
        // phdr fields
        let fo = match bits {
            Bitness::B32 => phdr32_field_offsets(),
            Bitness::B64 => phdr64_field_offsets(),
        };
        let classes = ["p_type", "p_flags", "p_offset", "p_vaddr", "p_paddr", "p_filesz", "p_memsz", "p_align"];
        for (k, &(off, size)) in fo.iter().enumerate() {
            v.push(Range {
                start: start + off,
                end: start + off + size,
                open: format!("<span class='{}'>", classes[k]),
                prio: 60,
                idx: (i as u32) * 10 + k as u32,
            });
        }
        let _ = p;
    }

    // Sections (those with non-zero size and not NOBITS type)
    for (i, s) in e.shdrs.iter().enumerate() {
        if s.sh_size == 0 { continue; }
        if s.sh_type == 8 /* SHT_NOBITS */ { continue; }
        if s.sh_type == 0 /* NULL */ { continue; }
        let start = s.sh_offset as usize;
        let end = start + s.sh_size as usize;
        if end > e.data.len() { continue; }
        v.push(Range {
            start,
            end,
            open: format!("<span class='bin_section{} section hover'>", i),
            prio: 55,
            idx: i as u32,
        });

        // If this section is inside a NOTE or GNU_PROPERTY segment, add segment_subrange
        let in_note = e.phdrs.iter().any(|p| {
            let ptype = p.p_type;
            (ptype == 4 || ptype == 0x6474e553)
                && p.p_offset != 0 && p.p_filesz > 0
                && (p.p_offset as usize) <= start
                && (p.p_offset as usize + p.p_filesz as usize) >= end
        });
        if in_note {
            v.push(Range {
                start,
                end,
                open: "<span class='segment_subrange hover'>".into(),
                prio: 70,
                idx: i as u32,
            });
        }
    }

    // Shdr entries
    let shentsize = e.ehdr.e_shentsize as usize;
    let shoff = e.ehdr.e_shoff as usize;
    for (i, _s) in e.shdrs.iter().enumerate() {
        let start = shoff + i * shentsize;
        let end = start + shentsize;
        if end > e.data.len() { continue; }
        v.push(Range {
            start,
            end,
            open: format!("<span class='bin_shdr{} shdr'>", i),
            prio: 50,
            idx: i as u32,
        });
        // shdr fields
        let fo = match bits {
            Bitness::B32 => shdr32_field_offsets(),
            Bitness::B64 => shdr64_field_offsets(),
        };
        let classes = ["sh_name", "sh_type", "sh_flags", "sh_addr", "sh_offset", "sh_size", "sh_link", "sh_info", "sh_addralign", "sh_entsize"];
        for (k, &(off, size)) in fo.iter().enumerate() {
            v.push(Range {
                start: start + off,
                end: start + off + size,
                open: format!("<span class='{}'>", classes[k]),
                prio: 60,
                idx: (i as u32) * 10 + k as u32,
            });
        }
    }

    v
}

fn phdr32_field_offsets() -> [(usize, usize); 8] {
    // ELF32 phdr order: type, offset, vaddr, paddr, filesz, memsz, flags, align
    [(0,4), (16,4), (4,4), (8,4), (20,4), (24,4), (12,4), (28,4)]
}

fn phdr64_field_offsets() -> [(usize, usize); 8] {
    // ELF64 phdr order: type, flags, offset, vaddr, paddr, filesz, memsz, align
    [(0,4), (4,4), (8,8), (16,8), (24,8), (32,8), (40,8), (48,8)]
}

fn shdr32_field_offsets() -> [(usize, usize); 10] {
    [(0,4),(4,4),(8,4),(12,4),(16,4),(20,4),(24,4),(28,4),(32,4),(36,4)]
}
fn shdr64_field_offsets() -> [(usize, usize); 10] {
    [(0,4),(4,4),(8,8),(16,8),(24,8),(32,8),(40,4),(44,4),(48,8),(56,8)]
}

fn write_ascii(out: &mut String, data: &[u8]) {
    out.push_str("    <div id='ascii'>");
    for (i, &b) in data.iter().enumerate() {
        if i > 0 && i % 16 == 0 {
            out.push('\n');
        }
        match b {
            b'<' => out.push_str("&lt;"),
            b'>' => out.push_str("&gt;"),
            b'&' => out.push_str("&amp;"),
            0x20..=0x7e => out.push(b as char),
            _ => out.push('.'),
        }
    }
    out.push_str("</div>\n");
}

fn write_sticky_table(out: &mut String, e: &ParsedElf) {
    out.push_str("    <table id='sticky_table' cellspacing='0'>\n");
    out.push_str("      <tr>\n");
    out.push_str("        <td id='desc'></td>\n");
    // First column: phdrs then shdrs
    out.push_str("        <td class='infotables'>\n");
    for (i, p) in e.phdrs.iter().enumerate() {
        write_phdr_info(out, i, p);
    }
    for (i, s) in e.shdrs.iter().enumerate() {
        write_shdr_info(out, i, s);
    }
    out.push_str("        </td>\n");
    // Second column: segments then sections
    out.push_str("        <td class='infotables'>\n");
    for (i, p) in e.phdrs.iter().enumerate() {
        write_segment_info(out, i, p, e);
    }
    for (i, s) in e.shdrs.iter().enumerate() {
        write_section_info(out, i, s, e);
    }
    out.push_str("        </td>\n");
    out.push_str("      </tr>\n");
    out.push_str("    </table>\n");
}

fn number_span(hex_title: bool, val: u64) -> String {
    if hex_title {
        format!("<span class='number' title='{:#x}'>{}</span>", val, val)
    } else {
        format!("<span class='number' title='{}'>{:#x}</span>", val, val)
    }
}

fn size_bytes(v: u64) -> String {
    // For "Size in file" style output - hex title, value is "N" or "N (X.Y KiB)"
    let base = format!("{}", v);
    let suffix = if v >= 1024 {
        let mut f = v as f64 / 1024.0;
        let mut units = ["KiB","MiB","GiB","TiB"];
        let mut i = 0;
        while f >= 1024.0 && i + 1 < units.len() {
            f /= 1024.0;
            i += 1;
        }
        format!(" ({:.1} {})", f, units[i])
    } else {
        String::new()
    };
    format!("<span class='number' title='{:#x}'>{}{}</span>", v, base, suffix)
}

fn write_phdr_info(out: &mut String, i: usize, p: &Phdr) {
    out.push_str(&format!("          <table class='conceal itable' id='info_phdr{}'>\n", i));
    out.push_str("          <th colspan='2' class='phdr_itable'></th>\n");
    out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", p_type_name(p.p_type)));
    out.push_str(&format!("            <tr> <td>Flags:</td> <td>{}</td> </tr>\n", p_flags_str(p.p_flags)));
    out.push_str(&format!("            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n", number_span(false, p.p_offset)));
    out.push_str(&format!("            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n", size_bytes(p.p_filesz)));
    out.push_str(&format!("            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n", number_span(false, p.p_vaddr)));
    out.push_str(&format!("            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n", size_bytes(p.p_memsz)));
    out.push_str(&format!("            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n", number_span(true, p.p_align)));
    out.push_str("          </table>\n");
}

fn write_shdr_info(out: &mut String, i: usize, s: &Shdr) {
    out.push_str(&format!("          <table class='conceal itable' id='info_shdr{}'>\n", i));
    out.push_str("          <th colspan='2' class='shdr_itable'></th>\n");
    out.push_str(&format!("            <tr> <td>Index:</td> <td>{}</td> </tr>\n", i));
    out.push_str(&format!("            <tr> <td>Name:</td> <td>{}</td> </tr>\n", s.name));
    out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", sh_type_name(s.sh_type)));
    // Flags shown as just string (not 0x value)
    out.push_str(&format!("            <tr> <td>Flags:</td> <td>{}</td> </tr>\n", sh_flags_str(s.sh_flags)));
    out.push_str(&format!("            <tr> <td>Vaddr in memory:</td> <td>{}</td> </tr>\n", number_span(false, s.sh_addr)));
    out.push_str(&format!("            <tr> <td>Offset in file:</td> <td>{}</td> </tr>\n", number_span(false, s.sh_offset)));
    out.push_str(&format!("            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n", size_bytes(s.sh_size)));
    out.push_str(&format!("            <tr> <td>Linked section:</td> <td>{}</td> </tr>\n", s.sh_link));
    out.push_str(&format!("            <tr> <td>Extra info:</td> <td>{}</td> </tr>\n", number_span(true, s.sh_info as u64)));
    out.push_str(&format!("            <tr> <td>Alignment:</td> <td>{}</td> </tr>\n", number_span(true, s.sh_addralign)));
    out.push_str(&format!("            <tr> <td>Size of entries:</td> <td>{}</td> </tr>\n", number_span(true, s.sh_entsize)));
    out.push_str("          </table>\n");
}

fn write_segment_info(out: &mut String, i: usize, p: &Phdr, e: &ParsedElf) {
    out.push_str(&format!("          <table class='conceal itable' id='info_segment{}'>\n", i));
    out.push_str("          <th colspan='2' class='segment_itable'></th>\n");
    out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", p_type_name(p.p_type)));
    out.push_str(&format!("            <tr> <td>Size in file:</td> <td>{}</td> </tr>\n", size_bytes(p.p_filesz)));
    out.push_str(&format!("            <tr> <td>Size in memory:</td> <td>{}</td> </tr>\n", size_bytes(p.p_memsz)));

    // Special info for INTERP and NOTE segments
    if p.p_type == 3 {
        let start = p.p_offset as usize;
        let end = start + p.p_filesz as usize;
        if end <= e.data.len() {
            let bytes = &e.data[start..end];
            let s = read_cstring(bytes);
            out.push_str("            <tr><td><br></td></tr>\n");
            out.push_str(&format!("            <tr> <td>Interpreter:</td> <td>{}</td> </tr>\n", s));
        }
    } else if p.p_type == 4 {
        // NOTE segment - parse notes
        let start = p.p_offset as usize;
        let end = start + p.p_filesz as usize;
        if end <= e.data.len() {
            write_notes(out, &e.data[start..end], e.endianness);
        }
    }

    out.push_str("          </table>\n");
}

fn write_section_info(out: &mut String, i: usize, s: &Shdr, e: &ParsedElf) {
    out.push_str(&format!("          <table class='conceal itable' id='info_section{}'>\n", i));
    out.push_str("          <th colspan='2' class='section_itable'></th>\n");
    out.push_str(&format!("            <tr> <td>Type:</td> <td>{}</td> </tr>\n", sh_type_name(s.sh_type)));
    out.push_str(&format!("            <tr> <td>Size:</td> <td>{}</td> </tr>\n", size_bytes(s.sh_size)));

    // For STRTAB sections, dump null-terminated strings
    if s.sh_type == 3 {
        let start = s.sh_offset as usize;
        let end = start + s.sh_size as usize;
        if end <= e.data.len() {
            let bytes = &e.data[start..end];
            let strings: Vec<String> = split_strtab(bytes);
            if !strings.is_empty() {
                out.push_str("            <tr><td><br></td></tr>\n");
                out.push_str("            <tr>\n");
                out.push_str("              <td></td>\n");
                out.push_str("              <td>\n");
                out.push_str("                <div>\n");
                for st in &strings {
                    out.push_str(&format!("                  {}\n", st));
                }
                out.push_str("                </div>\n");
                out.push_str("              </td>\n");
                out.push_str("            </tr>\n");
            }
        }
    }

    out.push_str("          </table>\n");
}

fn read_cstring(bytes: &[u8]) -> String {
    let end = bytes.iter().position(|&b| b == 0).unwrap_or(bytes.len());
    String::from_utf8_lossy(&bytes[..end]).into_owned()
}

fn split_strtab(bytes: &[u8]) -> Vec<String> {
    let mut result = Vec::new();
    let mut start = 0;
    for (i, &b) in bytes.iter().enumerate() {
        if b == 0 {
            if i > start {
                result.push(String::from_utf8_lossy(&bytes[start..i]).into_owned());
            }
            start = i + 1;
        }
    }
    result
}

fn write_notes(out: &mut String, bytes: &[u8], endianness: Endianness) {
    // Notes format: name_size (4), desc_size (4), type (4), name (padded to 4), desc (padded to 4)
    let mut pos = 0;
    while pos + 12 <= bytes.len() {
        let namesz = read_u32(bytes, pos, endianness) as usize;
        let descsz = read_u32(bytes, pos + 4, endianness) as usize;
        let ntype = read_u32(bytes, pos + 8, endianness);
        pos += 12;
        if pos + namesz > bytes.len() { break; }
        let name_end = if namesz > 0 { pos + namesz - 1 } else { pos }; // exclude trailing null
        let name = String::from_utf8_lossy(&bytes[pos..name_end]).into_owned();
        pos += align4(namesz);
        if pos + descsz > bytes.len() { break; }
        let desc = &bytes[pos..pos + descsz];
        pos += align4(descsz);

        out.push_str("            <tr><td><br></td></tr>\n");
        out.push_str(&format!("            <tr> <td>Name:</td> <td>{}</td> </tr>\n", name));
        out.push_str(&format!("            <tr> <td>Type:</td> <td>{:#x}</td> </tr>\n", ntype));
        // Desc handling depends
        if name == "GNU" && ntype == 3 {
            // Build ID (hex)
            let bid: String = desc.iter().map(|b| format!("{:02x}", b)).collect();
            out.push_str(&format!("            <tr> <td>Build ID:</td> <td>{}</td> </tr>\n", bid));
        } else {
            let mut s = String::new();
            for (i, b) in desc.iter().enumerate() {
                if i > 0 { s.push(' '); }
                s.push_str(&format!("<b>{:02x}</b>", b));
            }
            if !s.is_empty() { s.push(' '); }
            out.push_str(&format!("            <tr> <td>Desc:</td> <td>{}</td> </tr>\n", s));
        }
    }
}

fn read_u32(bytes: &[u8], offset: usize, e: Endianness) -> u32 {
    let mut b = [0u8; 4];
    b.copy_from_slice(&bytes[offset..offset + 4]);
    match e {
        Endianness::Little => u32::from_le_bytes(b),
        Endianness::Big => u32::from_be_bytes(b),
    }
}

fn align4(n: usize) -> usize {
    (n + 3) & !3
}

fn build_highlight_calls(_e: &ParsedElf) -> String {
    let mut s = String::new();
    s.push_str("      highlightClasses('fileinfo_class', 'class')\n");
    s.push_str("      highlightClasses('fileinfo_data', 'data')\n");
    s.push_str("      highlightClasses('fileinfo_abi', 'abi')\n");
    s.push_str("      highlightClasses('fileinfo_abi_ver', 'abi_ver')\n");
    s.push_str("      highlightClasses('fileinfo_e_type', 'e_type')\n");
    s.push_str("      highlightClasses('fileinfo_e_machine', 'e_machine')\n");
    s.push_str("      highlightClasses('fileinfo_e_entry', 'e_entry')\n");
    s.push_str("      highlightClasses('fileinfo_e_phoff', 'e_phoff')\n");
    s.push_str("      highlightClasses('fileinfo_e_shoff', 'e_shoff')\n");
    s.push_str("      highlightClasses('fileinfo_e_flags', 'e_flags')\n");
    s.push_str("      highlightClasses('fileinfo_e_ehsize', 'e_ehsize')\n");
    s.push_str("      highlightClasses('fileinfo_e_phentsize', 'e_phentsize')\n");
    s.push_str("      highlightClasses('fileinfo_e_phnum', 'e_phnum')\n");
    s.push_str("      highlightClasses('fileinfo_e_shentsize', 'e_shentsize')\n");
    s.push_str("      highlightClasses('fileinfo_e_shnum', 'e_shnum')\n");
    s.push_str("      highlightClasses('fileinfo_e_shstrndx', 'e_shstrndx')\n");
