    for i in 0..e.phdrs.len() {
        s.push_str(&format!("      connect('.bin_phdr{} > .p_offset', '.bin_segment{}');\n", i, i));
    }
    for i in 0..e.shdrs.len() {
        s.push_str(&format!("      connect('.bin_shdr{} > .sh_offset', '.bin_section{});\n", i, i));
        let link = e.shdrs[i].sh_link;
        if link != 0 && (link as usize) < e.shdrs.len() {
            s.push_str(&format!("      connect('.bin_shdr{} > .sh_link', '.bin_shdr{}');\n", i, link));
        }
    }
    s
}
